extra.7bada7afc84fdf8e:
ツアーオブ{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.93);display:none;align-items:center;justify-content:center;padding:20px}
      ツアー・オブ・ヴィス{display:flex}
      ツアーボックス{background:#0a0a0a;border:1.5px solid #12A5FF;border-radius:20px;padding:36px 28px 24px;max-width:420px;width:100%;font-family:inherit}
      tslide{display:none;min-height:160px}
      tslide.on{display:block}
      tslide アイコン{font-size:30px;text-align:center;margin-bottom:14px}
      tslideキッカー{font-size:9px;font-weight:900;letter-spacing:3px;color:#12A5FF;text-transform:uppercase;text-align:center;margin-bottom:12px}
      tslide ボディ{font-size:15px;line-height:1.8;color:rgba(255,255,255,.88);text-align:center}
      tslide ボディ B{color:#ff0000}
      tslide ボディエム{color:#12A5FF;font-style:normal;font-weight:700}
      ドッグ{display:flex;gap:7px;justify-content:center;margin:22px 0 16px}
      tdot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.2);cursor:pointer;transition:background .2s}
      tdot.on{background:#12A5FF}
      TNV{display:flex;align-items:center;gap:8px}
      スカイ{flex:1;background:none;border:none;color:rgba(255,255,255,.3);font-size:11px;letter-spacing:1px;cursor:pointer;font-family:inherit;text-align:left;padding:0}
      トップ >{background:none;border:1px solid rgba(255,255,255,.2);color:rgba(255,255,255,.5);font-size:14px;padding:9px 14px;border-radius:8px;cursor:pointer;font-family:inherit}
      t 次へ{background:#12A5FF;border:none;color:#000;font-size:12px;font-weight:900;padding:10px 22px;border-radius:10px;cursor:pointer;font-family:inherit;letter-spacing:1px;white-space:nowrap}
      ヘルプBDN{position:fixed;bottom:24px;right:24px;z-index:998;width:52px;height:52px;border-radius:50%;background:#ff0000;border:2px solid rgba(255,255,255,.25);color:#fff;font-size:22px;font-weight:900;cursor:pointer;font-family:inherit;animation:phb 2s ease-in-out infinite;display:flex;align-items:center;justify-content:center}
      キーフレーム phb{0%,100%{box-shadow:0 0 0 0 rgba(255,0,0,.65),0 0 12px rgba(255,0,0,.3)}55%{box-shadow:0 0 0 18px rgba(255,0,0,0),0 0 22px rgba(255,0,0,.1)}助け{position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.88);display:none;align-items:center;justify-content:center;padding:20px}
      ヘルプ・オブ・ヴィス{display:flex}
      助手ボックス{background:#0a0a0a;border:1.5px solid #ff0000;border-radius:16px;padding:28px 22px;max-width:420px;width:100%;font-family:inherit;box-shadow:0 0 30px rgba(255,0,0,.12)}
      ヘルプセック{font-size:9px;font-weight:900;letter-spacing:2.5px;color:#ff0000;text-transform:uppercase;margin-bottom:10px}
      ヘルプテキスト{font-size:14px;line-height:1.75;color:rgba(255,255,255,.9);margin:0 0 20px;white-space:pre-wrap}
      HBTS{display:flex;gap:8px}
      Hツアー{flex:1;background:rgba(18,165,255,.08);border:1px solid #12A5FF;color:#12A5FF;font-size:11px;font-weight:700;letter-spacing:1px;padding:10px;border-radius:8px;cursor:pointer;font-family:inherit}
      H - 閉鎖{flex:1;background:#ff0000;border:none;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;padding:10px;border-radius:8px;cursor:pointer;font-family:inherit}

extra.69584882b10d35ad:
リクエストビュー{position:fixed;inset:0;z-index:9999;display:none;
      background:#000;color:#fff;overflow-y:auto;
      font-family:Inter,system-ui,sans-serif;}
    EQV ヘッダー{position:sticky;top:0;z-index:2;
      background:rgba(0,0,0,0.92);backdrop-filter:blur(6px);
      padding:16px;display:flex;align-items:center;justify-content:space-between;
      border-bottom:1px solid rgba(255,255,255,0.08);}
    タイトルEqv{font-size:12px;font-weight:900;letter-spacing:2.5px;
      color:#12A5FF;text-shadow:0 0 8px #12A5FF;text-transform:uppercase;}
    EQV 閉鎖{background:transparent;border:1.5px solid rgba(255,255,255,0.35);
      color:#fff;border-radius:20px;padding:8px 16px;font-size:11px;
      font-weight:700;letter-spacing:1px;cursor:pointer;text-transform:uppercase;
      font-family:inherit;}
    タイトル:HOVER{background:rgba(255,255,255,0.08);}
    グリッドEqv{display:flex;flex-direction:column;align-items:center;
      gap:36px;padding:20px 20px 40px;max-width:480px;margin:0 auto;}
    EQVカード{display:flex;flex-direction:column;align-items:center;gap:12px;width:100%;}
    タイトル:Eqv-type-header{display:flex;align-items:center;justify-content:center;
      gap:9px;width:100%;}
    トップ > ドット{width:13px;height:13px;border-radius:50%;flex-shrink:0;}
    タイトル / タグ{font-size:16px;font-weight:900;letter-spacing:1.2px;
      text-transform:uppercase;text-align:center;line-height:1.25;}
    EQVカバー{position:relative;border-radius:30px;background:#0a1422;
      display:flex;align-items:center;justify-content:center;overflow:hidden;}
    eqvカバー img, . eqv -cover canvas{width:90%;height:90%;object-fit:contain;
      border-radius:10px;background:#fff;display:block;}
    EQV名{font-size:13px;color:rgba(255,255,255,0.75);text-align:center;
      letter-spacing:0.3px;word-break:break-word;}
